#include <stdio.h>

int main(int argc, char *argv[])
{
    long long a,b,c=1;
    scanf("%lld",&a);
    b=a-1;
    while(b>0)
    {
        c = (c * 3) % 1000003;
        b--;
    }
    printf("%lld",c%(1000000+3));
    return 0;
}

